const assert = require('node:assert/strict');
const fs = require('node:fs');
const path = require('node:path');
const http = require('node:http');
const {chromium} = require('playwright');
const ROOT=path.resolve(__dirname,'..'), OUT=path.join(ROOT,'results');
const APP_FILE=path.join(ROOT,'board_game_tracker_v20.html');
const STORE='quest-for-glory-v12-slots';
const ALL=['H','S','C','D'].flatMap(s=>Array.from({length:13},(_,i)=>s+(i+1)));
const cost=ids=>ids.reduce((n,id)=>n+Number(id.slice(1))*(id[0]==='D'?2:1),0);
function fixture(over={}) {const base={started:true,round:0,characterName:'Baseline Hero',adventureModule:'Audit',inventory:[],dead:false,res:{Coin:8,Fate:4,Supply:2},zones:{deck:['H1','H2','H3','S4','C5','D6'],hand:[],fatigue:[],wound:[]},log:[],challenge:null,combat:null,woundTask:null,pointLimit:50,upgradePoints:23,diceType:'6',diceHistory:[]};const x={...base,...over};x.pool=over.pool??ALL.filter(id=>!Object.values(x.zones).flat().includes(id));x.upgradePoints=over.upgradePoints??x.pointLimit-cost(Object.values(x.zones).flat());return x;}
const slot=(state,id='one')=>({id,state,updated:1});
const cases=[];function test(name,fn){cases.push({name,fn});}
async function click(p,s){await p.locator(s).click();}
async function read(p,id='one'){return p.evaluate(({STORE,id})=>JSON.parse(localStorage.getItem(STORE)).slots.find(s=>s.id===id)?.state,{STORE,id});}
async function seed(p,states=[slot(fixture())],key=STORE){await p.evaluate(({key,states})=>{localStorage.clear();localStorage.setItem(key,JSON.stringify({slots:states}));},{key,states});await p.reload();}
async function load(p,s=fixture()){await seed(p,[slot(s)]);await click(p,'[data-continue="one"]');}
async function random(p,n=.4){await p.evaluate(n=>Math.random=()=>n,n);}
async function action(p,m){await click(p,`[data-mode="${m}"]`);}
async function pick(p,ids){for(const id of ids)await click(p,`#operation [data-card="${id}"]:not([disabled])`);}
async function challenge(p,ids=['H3'],base=5){await action(p,'challenge');await p.locator('#difficulty').fill(String(base));await click(p,'#begin');await pick(p,ids);await click(p,'#commitChallenge');}
async function combat(p,ids=['H1'],base=20,wound=1){await action(p,'combat');await p.locator('#combatDifficulty').fill(String(base));await p.locator('#combatWound').fill(String(wound));await click(p,'#startCombat');await pick(p,ids);await click(p,'#combatCommit');}
function invariant(s){const owned=Object.values(s.zones).flat();assert.equal(new Set(owned).size,owned.length,'owned cards unique');assert.equal(new Set([...owned,...s.pool]).size,52,'all 52 cards accounted for');assert.equal(owned.length+s.pool.length,52,'pool has no missing/duplicate cards');}
async function wound(p,n,deck=[]){await action(p,'wound');await p.locator('#woundValue').fill(String(n));await click(p,'#beginWound');await click(p,'#woundNext');if(await p.locator('#finishWound').count()){await pick(p,deck);await click(p,'#finishWound');}}
async function addItem(p,{desc='Rope',base=2,purchased=false,price=base}={}){await click(p,'#inventoryAdd');await p.locator('#inventoryDescription').fill(desc);await p.locator('#inventoryBaseValue').fill(String(base));if(purchased){await p.locator('#inventoryPurchased').check();await p.locator('#inventoryPurchasePrice').fill(String(price));}await click(p,'#inventoryItemConfirm');}
async function importData(p,data){await p.locator('#importfile').setInputFiles({name:'character.json',mimeType:'application/json',buffer:Buffer.from(JSON.stringify(data))});await p.waitForTimeout(120);}

test('01 creation defaults, random name, double Diamond cost, initial pool',async p=>{await click(p,'#createCharacter');assert.ok((await p.locator('#characterName').inputValue()).split(' ').length===2);for(const [k,n]of Object.entries({Coin:8,Fate:4,Supply:2}))assert.equal(await p.locator(`[data-start="${k}"]`).inputValue(),String(n));await click(p,'#setupCards [data-card="D6"]');assert.match(await p.locator('#setupTotal').innerText(),/12 \/ 50/);await click(p,'#startGame');const s=await p.evaluate(STORE=>JSON.parse(localStorage.getItem(STORE)).slots[0].state,STORE);assert.equal(s.upgradePoints,38);invariant(s);});
test('02 creation rejects overspend and supports custom starting values',async p=>{await click(p,'#createCharacter');await p.locator('#pointLimit').fill('5');await p.locator('#pointLimit').press('Tab');await click(p,'#setupCards [data-card="D6"]');assert.equal(await p.locator('#startGame').isDisabled(),true);await click(p,'#setupCards [data-card="D6"]');await click(p,'#setupCards [data-card="H1"]');await p.locator('[data-start="Coin"]').fill('13');await p.locator('[data-start="Coin"]').press('Tab');await click(p,'#startGame');assert.equal(await p.locator('#resources strong').first().innerText(),'13');});
test('03 autosave and reload preserve resources, cards, inventory',async p=>{await load(p,fixture({inventory:[{description:'Rope',keywords:'tool',baseValue:2}]}));await click(p,'[data-resource="Coin"][data-delta="1"]');const s=await read(p);await p.reload();await click(p,'[data-continue="one"]');assert.deepEqual(await read(p),s);assert.match(await p.locator('#inventoryEntries').innerText(),/Rope/);});
test('04 independent slots and five-slot creation/import capacity',async p=>{const slots=Array.from({length:5},(_,i)=>slot(fixture({characterName:'Hero '+i}),String(i)));await seed(p,slots);assert.equal(await p.locator('#createCharacter').isDisabled(),true);await click(p,'#importCharacter');assert.match(await p.locator('#status').innerText(),/5 save slots/);await click(p,'[data-continue="0"]');await click(p,'[data-resource="Coin"][data-delta="1"]');assert.equal((await read(p,'0')).res.Coin,9);assert.equal((await read(p,'1')).res.Coin,8);});
test('05 deletion requires in-app confirmation and Cancel preserves character',async p=>{await seed(p);await click(p,'[data-delete="one"]');assert.equal(await p.locator('#deleteModal').isVisible(),true);await click(p,'#deleteCancel');assert.ok(await read(p));await click(p,'[data-delete="one"]');await click(p,'#deleteConfirm');assert.equal(await p.locator('[data-continue]').count(),0);});
test('06 JSON download/import roundtrip preserves character',async p=>{await seed(p);const download=p.waitForEvent('download');await click(p,'[data-export="one"]');const d=await download;const raw=JSON.parse(fs.readFileSync(await d.path(),'utf8'));assert.equal(raw.format,'quest-for-glory-character');const before=await read(p);await importData(p,raw);const all=await p.evaluate(STORE=>JSON.parse(localStorage.getItem(STORE)).slots,STORE);assert.equal(all.length,2);assert.deepEqual(all[1].state,before);});
test('07 invalid duplicate-card JSON rejected without overwriting save',async p=>{await seed(p);const s=fixture();s.zones.fatigue=['H1'];await importData(p,s);assert.match(await p.locator('#status').innerText(),/Import failed/);assert.equal(await p.locator('[data-continue]').count(),1);});
test('08 resource edits logged, zero protected and Undo restores state',async p=>{await load(p,fixture({res:{Coin:0,Fate:4,Supply:2}}));assert.equal(await p.locator('[data-resource="Coin"][data-delta="-1"]').isDisabled(),true);assert.equal((await read(p)).res.Coin,0);await click(p,'[data-resource="Coin"][data-delta="1"]');assert.match((await read(p)).log[0].message,/Coin \+1/);await click(p,'#undo');assert.equal((await read(p)).res.Coin,0);});
test('09 delegated card-zone tiles work after repeated UI refreshes',async p=>{await load(p);for(const z of ['deck','fatigue','wound']){await click(p,`[data-viewzone="${z}"] .zone-title`);assert.equal(await p.locator('#zoneView').isVisible(),true);await click(p,'[data-resource="Coin"][data-delta="1"]');await click(p,`[data-viewzone="${z}"] .zone-total`);assert.equal(await p.locator('#zoneView').isVisible(),false);}});
test('10 challenge success moves hand to Fatigue and preserves all cards',async p=>{await load(p);await random(p);await challenge(p,['C5'],4);await click(p,'#resolve');const s=await read(p);assert.deepEqual(s.zones.fatigue,['C5']);assert.equal(s.challenge,null);assert.equal(s.dead,false);invariant(s);});
test('11 challenge failure is logged and cards move to Fatigue',async p=>{await load(p);await random(p);await challenge(p,['H1'],10);await click(p,'#resolve');const s=await read(p);assert.match(s.log[0].message,/FAILURE/);assert.deepEqual(s.zones.fatigue,['H1']);invariant(s);});
test('12 modifier six equal random buckets produce -6,-3,0,0,3,6',async p=>{const got=[];for(let i=0;i<6;i++){await load(p);await random(p,(i+.5)/6);await challenge(p);got.push((await read(p)).challenge.modifier);await click(p,'#cancelEncounter');}assert.deepEqual(got,[-6,-3,0,0,3,6]);});
test('13 excluded suits blocked at hand selection and Fate-add stage',async p=>{await load(p);await random(p);await action(p,'challenge');await click(p,'[data-suit="H"]');await click(p,'[data-suit="S"]');await click(p,'[data-suit="C"]');assert.equal(await p.locator('#luckOnlyWarning').isVisible(),true);await click(p,'#begin');assert.equal(await p.locator('#operation [data-card]').count(),1);await pick(p,['D6']);await click(p,'#commitChallenge');assert.equal(await p.locator('#add').isDisabled(),true);});
test('14 first Fate adjustment costs one and the next costs two',async p=>{for(const remove of [false,true]){await load(p);await random(p);await challenge(p,['H3']);await click(p,remove?'#remove':'#add');const id=remove?'H3':'H2';await pick(p,[id]);await click(p,'#apply');const s=await read(p);assert.equal(s.res.Fate,3);assert.equal(s.challenge.adjusted,true);assert.equal(await p.locator('#add').isEnabled(),true);assert.equal(await p.locator('#remove').isDisabled(),s.zones.hand.length===0);assert.match(await p.locator('#add').innerText(),/2 Fate/);invariant(s);}});
test('15 exact-match recovery returns selected cards and conserves deck',async p=>{await load(p);await random(p);await challenge(p,['H2','H3'],5);await click(p,'#resolve');await pick(p,['H2','H3']);await click(p,'#finishExact');const s=await read(p);assert.equal(s.zones.fatigue.length,0);assert.equal(s.zones.deck.length,6);invariant(s);});
test('16 exact-match permits choosing fewer than two cards (spec: up to two)',async p=>{await load(p);await random(p);await challenge(p,['H2','H3'],5);await click(p,'#resolve');await pick(p,['H2']);assert.equal(await p.locator('#finishExact').isEnabled(),true,'one returned card should be permitted');});
test('17 challenge Cancel restores complete pre-action persistent state',async p=>{await load(p);const before=await read(p);await random(p);await challenge(p);await click(p,'#add');await pick(p,['H2']);await click(p,'#apply');await click(p,'#cancelEncounter');assert.deepEqual(await read(p),before);});
test('18 combat success and exact recovery',async p=>{await load(p);await random(p);await combat(p,['C5'],4);await click(p,'#combatResolve');assert.equal((await read(p)).combat,null);await combat(p,['H2','H3'],5);await click(p,'#combatResolve');await pick(p,['H2','H3']);await click(p,'#combatExact');const s=await read(p);assert.equal(s.combat,null);invariant(s);});
test('19 combat retries reduce difficulty by two and Cancel restores before all retries',async p=>{await load(p);const before=await read(p);await random(p);await combat(p,['H1'],20);await click(p,'#combatResolve');await pick(p,['H1']);await click(p,'#woundNext');await click(p,'#combatRetry');assert.match(await p.locator('#operation').innerText(),/Base challenge 18/);await pick(p,['H2']);await click(p,'#combatCommit');await click(p,'#combatResolve');await pick(p,['H2']);await click(p,'#woundNext');await click(p,'#combatRetry');assert.match(await p.locator('#operation').innerText(),/Base challenge 16/);await click(p,'#cancelEncounter');assert.deepEqual(await read(p),before);});
test('20 combat fleeing costs two Fate; insufficient Fate disables flee',async p=>{for(const fate of [4,1]){await load(p,fixture({res:{Coin:8,Fate:fate,Supply:2}}));await random(p);await combat(p);await click(p,'#combatResolve');await pick(p,['H1']);await click(p,'#woundNext');if(fate===1)assert.equal(await p.locator('#combatFlee').isDisabled(),true);else{await click(p,'#combatFlee');assert.equal((await read(p)).res.Fate,2);assert.equal((await read(p)).combat,null);}}});
test('21 empty deck cannot begin challenge',async p=>{await load(p,fixture({zones:{deck:[],hand:[],fatigue:['H1'],wound:[]}}));await action(p,'challenge');assert.equal(await p.locator('#status').innerText(),'Unable to start a challenge without attribute cards');});
test('22 combat retry uses Fatigue hand for explicit two-Fate cost',async p=>{await load(p,fixture({zones:{deck:['H1','H2'],hand:[],fatigue:[],wound:[]}}));await random(p);await combat(p,['H1','H2']);await click(p,'#combatResolve');await pick(p,['H1']);await click(p,'#woundNext');await click(p,'#combatRetry');assert.match(await p.locator('#combatCommit').innerText(),/Spend 2 Fate/);await pick(p,['H2']);await click(p,'#combatCommit');assert.equal((await read(p)).res.Fate,2);invariant(await read(p));});
test('23 wounds use Fatigue exclusively when it can cover target',async p=>{await load(p,fixture({zones:{deck:['H3','H4'],hand:[],fatigue:['S2','C5'],wound:[]}}));await action(p,'wound');await p.locator('#woundValue').fill('4');await click(p,'#beginWound');assert.equal(await p.locator('#operation [data-card="H3"]').count(),0);await pick(p,['C5']);await click(p,'#woundNext');const s=await read(p);assert.deepEqual(s.zones.wound,['C5']);assert.deepEqual(s.zones.deck,['H3','H4']);invariant(s);});
test('24 insufficient Fatigue is fully allocated before deck cards',async p=>{await load(p,fixture({zones:{deck:['H3','H4'],hand:[],fatigue:['S2'],wound:[]}}));await wound(p,5,['H3']);const s=await read(p);assert.deepEqual(s.zones.wound,['S2','H3']);invariant(s);});
test('25 all owned cards wounded means persistent Game Over and disabled actions',async p=>{await load(p,fixture({zones:{deck:['H1'],hand:[],fatigue:[],wound:[]}}));await wound(p,5);assert.equal((await read(p)).dead,true);assert.equal(await p.locator('#gameOver').isVisible(),true);assert.equal(await p.locator('[data-mode="rest"]').isDisabled(),true);await p.reload();assert.equal(await p.locator('.slot-gameover .gameover-label').innerText(),'GAME OVER');await click(p,'[data-continue="one"]');assert.equal(await p.locator('#gameOver').isVisible(),true);});
test('26 successful challenge does not trigger empty-deck failure death',async p=>{await load(p,fixture({res:{Coin:0,Fate:0,Supply:0},zones:{deck:['H3'],hand:[],fatigue:[],wound:['H1']}}));await random(p);await challenge(p,['H3'],2);await click(p,'#resolve');assert.equal((await read(p)).dead,false);});
test('27 failed challenge detects empty deck + Fatigue + Wounds + Fate below two',async p=>{await load(p,fixture({res:{Coin:0,Fate:1,Supply:0},zones:{deck:['H3'],hand:[],fatigue:[],wound:['H1']}}));await random(p);await challenge(p,['H3'],10);await click(p,'#resolve');assert.equal((await read(p)).dead,true);});
test('28 Rest spends one Supply and enforces recovery value',async p=>{await load(p,fixture({zones:{deck:['H3'],hand:[],fatigue:['H1','H2'],wound:[]}}));await action(p,'rest');await p.locator('#target').fill('1');await pick(p,['H2']);assert.equal(await p.locator('#commit').isDisabled(),true);await pick(p,['H2','H1']);await click(p,'#commit');const s=await read(p);assert.equal(s.res.Supply,1);assert.ok(s.zones.deck.includes('H1'));invariant(s);});
test('29 Rest without Supply wounds five points before recovery',async p=>{await load(p,fixture({res:{Coin:8,Fate:4,Supply:0},zones:{deck:['H3'],hand:[],fatigue:['C5','H2'],wound:[]}}));await action(p,'rest');await click(p,'#restWoundStart');await pick(p,['C5']);await click(p,'#woundNext');await p.locator('#target').fill('2');await pick(p,['H2']);await click(p,'#commit');const s=await read(p);assert.deepEqual(s.zones.wound,['C5']);assert.deepEqual(s.zones.fatigue,[]);assert.equal(s.res.Supply,0);invariant(s);});
test('30 Healing recovers owned Wounds only, within value',async p=>{await load(p,fixture({zones:{deck:['H3'],hand:[],fatigue:[],wound:['H1','H2']}}));await action(p,'heal');await p.locator('#target').fill('1');await pick(p,['H2']);assert.equal(await p.locator('#commit').isDisabled(),true);await pick(p,['H2','H1']);await click(p,'#commit');assert.deepEqual((await read(p)).zones.wound,['H2']);invariant(await read(p));});
test('31 upgrades use leftover budget, Diamonds double, Fate buys three points',async p=>{await load(p);await action(p,'upgrade');await pick(p,['D13']);assert.equal(await p.locator('#purchaseCards').isDisabled(),true);await pick(p,['D13','D1']);await click(p,'#purchaseCards');let s=await read(p);assert.equal(s.upgradePoints,21);assert.ok(s.zones.deck.includes('D1'));await click(p,'#buyUpgrade');s=await read(p);assert.equal(s.pointLimit,53);assert.equal(s.upgradePoints,24);assert.equal(s.res.Fate,3);invariant(s);});
test('32 inventory purchase/sale, custom price, persisted data and Undo',async p=>{await load(p);await click(p,'#inventoryToggle');await addItem(p,{purchased:true,price:3});let s=await read(p);assert.equal(s.res.Coin,5);assert.equal(s.inventory[0].baseValue,2);assert.match(s.log[0].message,/Purchased/);await click(p,'[data-remove-item="0"]');assert.equal(await p.locator('#inventorySalePrice').inputValue(),'2');await p.locator('#inventorySold').check();await p.locator('#inventorySalePrice').fill('4');await click(p,'#inventoryRemoveConfirm');s=await read(p);assert.equal(s.res.Coin,9);assert.equal(s.inventory.length,0);await click(p,'#undo');assert.equal((await read(p)).inventory.length,1);});
test('33 insufficient Coin rejects item purchase with no state mutation',async p=>{await load(p);await click(p,'#inventoryToggle');const before=await read(p);await addItem(p,{purchased:true,price:9});assert.match(await p.locator('#inventoryError').innerText(),/Not enough/);assert.deepEqual(await read(p),{...before,inventoryTipsSeen:{purchase:true}});});
test('34 inventory eight-item limit and combined 300-character bound',async p=>{await load(p,fixture({inventory:Array.from({length:7},(_,i)=>({description:'item '+i,keywords:'',baseValue:1}))}));await click(p,'#inventoryToggle');await click(p,'#inventoryAdd');await p.locator('#inventoryDescription').fill('x'.repeat(290));await p.locator('#inventoryKeywords').fill('k'.repeat(20));assert.ok((await p.locator('#inventoryKeywords').inputValue()).length<=10);await click(p,'#inventoryItemConfirm');assert.equal((await read(p)).inventory.length,8);assert.equal(await p.locator('#inventoryAdd').isDisabled(),true);});
test('35 dice open does not roll; all types roll on tap with valid ranges',async p=>{await load(p);assert.equal(await p.locator('#diceBody').isVisible(),false);await click(p,'#diceToggle');assert.equal((await read(p)).diceHistory.length,0);for(const [type,min,max]of [['6',1,6],['8',1,8],['10',1,10],['12',1,12],['2d6',11,66]]){await click(p,`label:has(input[value="${type}"]) span`);await p.waitForTimeout(750);const s=await read(p),r=s.lastDice.result;assert.ok(r>=min&&r<=max);if(type==='2d6')assert.ok(r%10>=1&&r%10<=6);assert.equal(s.diceHistory[0].type,type==='2d6'?'2D6':'D'+type);}});
test('36 2D6 concatenates independent digits and history is newest-first capped at 20',async p=>{await load(p,fixture({diceHistory:Array.from({length:20},()=>({type:'D6',result:1}))}));await p.evaluate(()=>{const xs=[1/6+.01,3/6+.01];let i=0;Math.random=()=>xs[i++%2]});await click(p,'#diceToggle');await click(p,'label:has(input[value="2d6"]) span');await p.waitForTimeout(750);const s=await read(p);assert.equal(s.lastDice.result,24);assert.equal(s.diceHistory.length,20);assert.equal(s.diceHistory[0].result,24);});
test('37 legacy v11 slot migration retains cards, inventory and resources',async p=>{const original=fixture({inventory:[{description:'Old item',keywords:'',baseValue:2}]});await seed(p,[slot(original)],'quest-for-glory-v11-slots');await click(p,'[data-continue="one"]');assert.deepEqual(await read(p),original);});
test('38 save import requires full card-pool partition',async p=>{await seed(p);const s=fixture({pool:[]});await importData(p,s);assert.match(await p.locator('#status').innerText(),/Import failed/,'missing unowned cards must not be silently accepted');});
test('39 malformed active-action JSON is rejected before storing',async p=>{await seed(p);await importData(p,fixture({challenge:{stage:'choose',allowed:'H'}}));assert.match(await p.locator('#status').innerText(),/Import failed/,'invalid action shape should be rejected');});
test('40 corrupt localStorage is preserved for recovery rather than erased',async p=>{await p.evaluate(STORE=>localStorage.setItem(STORE,'{corrupt-saved-data'),STORE);await p.reload();assert.equal(await p.evaluate(STORE=>localStorage.getItem(STORE),STORE),'{corrupt-saved-data');});
test('41 paid no-Supply Rest can resume after reload without a second wound',async p=>{await load(p,fixture({res:{Coin:8,Fate:4,Supply:0},zones:{deck:['H3'],hand:[],fatigue:['C5','H2'],wound:[]}}));await action(p,'rest');await click(p,'#restWoundStart');await pick(p,['C5']);await click(p,'#woundNext');assert.equal((await read(p)).restWoundResolved,true);await p.reload();await click(p,'[data-continue="one"]');await action(p,'rest');assert.equal(await p.locator('#restWoundStart').count(),0,'already paid wound must not be charged again');});
test('42 dice roll belongs to original character when switching during animation',async p=>{await seed(p,[slot(fixture(),'one'),slot(fixture({characterName:'Other'}),'two')]);await click(p,'[data-continue="one"]');await click(p,'#diceToggle');await click(p,'label:has(input[value="6"]) span');await click(p,'#newGameTop');await click(p,'[data-continue="two"]');await p.waitForTimeout(750);assert.equal((await read(p,'two')).diceHistory.length,0,'other character must not receive pending roll');assert.equal((await read(p,'one')).diceHistory.length,1,'origin character should receive roll');});
test('43 character UI collapse defaults reset on character switch',async p=>{await seed(p,[slot(fixture(),'one'),slot(fixture(),'two')]);await click(p,'[data-continue="one"]');await click(p,'#diceToggle');await click(p,'#activityToggle');await click(p,'#newGameTop');await click(p,'[data-continue="two"]');assert.equal(await p.locator('#diceBody').isVisible(),false);assert.equal(await p.locator('#activityBody').isVisible(),false);});
test('44 Game Over prevents new dice results',async p=>{await load(p,fixture({dead:true}));await click(p,'#diceToggle');await click(p,'label:has(input[value="6"]) span');await p.waitForTimeout(750);assert.equal((await read(p)).diceHistory.length,0);});
test('45 challenge mid-action reload retains hand and Cancel rollback',async p=>{await load(p);const before=await read(p);await random(p);await challenge(p);const committed=await read(p);await p.reload();await click(p,'[data-continue="one"]');assert.deepEqual(await read(p),committed);await click(p,'#cancelEncounter');assert.deepEqual(await read(p),before);});
test('46 selected cards keep ivory, tilt and shadow with a thin dark border',async p=>{await click(p,'#createCharacter');const card=p.locator('#setupCards [data-card="H1"]');await card.click();await p.waitForTimeout(250);for(const interaction of ['normal','hover','focus']){if(interaction==='normal'){await p.mouse.move(0,0);await card.evaluate(e=>e.blur())}if(interaction==='hover')await card.hover();if(interaction==='focus'){await p.mouse.move(0,0);await card.focus()}const css=await card.evaluate(e=>{const s=getComputedStyle(e);return {bg:s.backgroundColor,transform:s.transform,border:s.borderColor,width:s.borderWidth,style:s.borderStyle,shadow:s.boxShadow}});assert.equal(css.bg,'rgb(255, 248, 232)');assert.equal(css.border,'rgb(73, 53, 43)');assert.equal(css.width,'1px');assert.equal(css.style,'solid');assert.notEqual(css.transform,'none');assert.notEqual(css.shadow,'none');}await card.click();await p.waitForTimeout(250);assert.equal(await card.evaluate(e=>e.classList.contains('selected')),false);assert.notEqual(await card.evaluate(e=>getComputedStyle(e).borderColor),'rgb(73, 53, 43)');});
test('47 release identifies itself as Version 20',async p=>{assert.match(await p.locator('header .muted').innerText(),/Version 20\b/);});
test('48 mobile touch: zone tiles, modal and no horizontal page overflow',async(p,ctx,browser)=>{const mobile=await browser.newContext({viewport:{width:390,height:844},isMobile:true,hasTouch:true,deviceScaleFactor:2});const q=await mobile.newPage();await q.goto(p.url());await load(q);await q.locator('[data-viewzone="deck"] .zone-title').tap();assert.equal(await q.locator('#zoneView').isVisible(),true);await click(q,'[data-resource="Coin"][data-delta="1"]');await q.locator('[data-viewzone="deck"] .zone-title').tap();assert.equal(await q.locator('#zoneView').isVisible(),false);await q.locator('#inventoryToggle').tap();await q.locator('#inventoryAdd').tap();assert.equal(await q.locator('#inventoryModal').isVisible(),true);assert.ok(await q.evaluate(()=>document.documentElement.scrollWidth<=innerWidth));await q.screenshot({path:path.join(OUT,'mobile-inventory.png'),fullPage:true});await mobile.close();});
test('49 supplied Righteous font is embedded, loads and applies to titles and names',async p=>{await seed(p);await p.evaluate(()=>document.fonts.ready);const fonts=await p.evaluate(()=>[...document.fonts].map(f=>({family:f.family,status:f.status})));assert.ok(fonts.some(f=>f.family==='RighteousEmbedded'&&f.status==='loaded'));for(const selector of ['header h1','.slot strong'])assert.match(await p.locator(selector).first().evaluate(e=>getComputedStyle(e).fontFamily),/RighteousEmbedded/);await click(p,'[data-continue="one"]');await p.evaluate(()=>document.fonts.ready);for(const selector of ['#characterHeading','#moduleHeading']){assert.match(await p.locator(selector).evaluate(e=>getComputedStyle(e).fontFamily),/RighteousEmbedded/);assert.equal(await p.locator(selector).evaluate(e=>getComputedStyle(e).fontWeight),'400');}});

test('50 old v6 single-character storage migrates into an independent slot',async p=>{const s=fixture();await p.evaluate(s=>{localStorage.clear();localStorage.setItem('adventure-tracker-v6',JSON.stringify(s));},s);await p.reload();await click(p,'[data-continue]');assert.equal(await p.locator('#characterHeading').innerText(),s.characterName);});
test('51 no-Supply Rest that wounds every card stops with Game Over',async p=>{await load(p,fixture({res:{Coin:0,Fate:4,Supply:0},zones:{deck:['H1'],hand:[],fatigue:[],wound:[]}}));await action(p,'rest');await click(p,'#restWoundStart');await click(p,'#woundNext');await click(p,'#finishWound');assert.equal((await read(p)).dead,true);assert.equal(await p.locator('#gameOver').isVisible(),true);});
test('52 eligible-suit filtering also applies to two-Fate Fatigue hand',async p=>{const before=fixture({zones:{deck:[],hand:[],fatigue:['H1','S2','D3'],wound:['C5']}});const rollback=JSON.stringify(before);before.challenge={base:5,modifier:null,stage:'choose',adjusted:false,allowed:['H','D'],rollback};await load(p,before);assert.equal(await p.locator('#operation [data-card="S2"]').count(),0);await pick(p,['H1']);await random(p);await click(p,'#commitChallenge');const s=await read(p);assert.equal(s.res.Fate,2);assert.deepEqual(s.zones.hand,['H1']);invariant(s);});
test('53 combat Fate adjustment costs one and subsequent use costs two',async p=>{await load(p);await random(p);await combat(p);await click(p,'#combatAdd');await pick(p,['H3']);await click(p,'#combatApply');const s=await read(p);assert.equal(s.res.Fate,3);assert.equal(s.combat.adjusted,true);assert.equal(await p.locator('#combatAdd').isEnabled(),true);assert.equal(await p.locator('#combatRemove').isEnabled(),true);assert.match(await p.locator('#combatAdd').innerText(),/2 Fate/);invariant(s);});
test('54 imported point balance cannot authorize purchases above point limit',async p=>{await seed(p);const s=fixture({pointLimit:27,upgradePoints:100});await importData(p,s);const imported=await p.locator('[data-continue]').last().getAttribute('data-continue');if(imported==='one'){assert.match(await p.locator('#status').innerText(),/Import failed/);return;}await click(p,`[data-continue="${imported}"]`);await action(p,'upgrade');await pick(p,['D13']);assert.equal(await p.locator('#purchaseCards').isDisabled(),true,'no available points at limit');});
test('55 storage write failure remains visible to player',async p=>{await load(p);await p.evaluate(()=>Storage.prototype.setItem=function(){throw new DOMException('Quota exceeded','QuotaExceededError')});await click(p,'[data-resource="Coin"][data-delta="1"]');assert.match(await p.locator('#status').innerText(),/Save failed/);});
test('56 imported encounter strings cannot insert executable markup',async p=>{await seed(p);const s=fixture({challenge:{base:'<img src="invalid" onerror="window.auditInjected=true">',modifier:0,stage:'decide',adjusted:false,allowed:['H','S','C','D'],rollback:'{}'}});await importData(p,s);const id=await p.locator('[data-continue]').last().getAttribute('data-continue');if(id==='one'){assert.match(await p.locator('#status').innerText(),/Import failed/);return;}await click(p,`[data-continue="${id}"]`);await p.waitForTimeout(200);assert.equal(await p.evaluate(()=>!!window.auditInjected),false,'imported challenge.base inserted executable HTML');});

test('57 app can create and resolve a challenge with networking disabled',async(p,ctx,browser)=>{const c=await browser.newContext({offline:true});const external=[];const origin=new URL(p.url()).origin;await c.route('**/*',r=>{if(new URL(r.request().url()).origin===origin)return r.fulfill({status:200,contentType:'text/html',body:fs.readFileSync(APP_FILE)});external.push(r.request().url());return r.abort()});const q=await c.newPage();await q.goto(origin);await click(q,'#createCharacter');await click(q,'#setupCards [data-card="H3"]');await click(q,'#startGame');await random(q);await challenge(q,['H3'],2);await click(q,'#resolve');assert.match(await q.locator('#log').innerText(),/SUCCESS/);assert.deepEqual(external,[]);await q.reload();assert.equal(await q.locator('[data-continue]').count(),1);await c.close();});

test('58 corrupt storage backup contains original bytes and loading retry recovers',async p=>{const original='{not valid JSON';await p.evaluate(({STORE,original})=>localStorage.setItem(STORE,original),{STORE,original});await p.reload();assert.equal(await p.locator('#storageNotice').isVisible(),true);assert.equal(await p.locator('#createCharacter').isDisabled(),true);assert.equal(await p.locator('#importCharacter').isDisabled(),true);const download=p.waitForEvent('download');await click(p,'#storageBackup');const d=await download;assert.equal(fs.readFileSync(await d.path(),'utf8'),original);assert.equal(await p.evaluate(STORE=>localStorage.getItem(STORE),STORE),original);await p.evaluate(({STORE,state})=>localStorage.setItem(STORE,JSON.stringify({slots:[{id:'one',state,updated:1}]})),{STORE,state:fixture()});await click(p,'#storageRetry');assert.equal(await p.locator('#storageNotice').isVisible(),false);await click(p,'[data-continue="one"]');assert.equal(await p.locator('#characterHeading').innerText(),'Baseline Hero');});
test('59 malformed slot data is preserved atomically instead of filtered or overwritten',async p=>{const raw=JSON.stringify({slots:[slot(fixture()),slot(fixture({zones:{deck:['H1'],hand:[],fatigue:['H1'],wound:[]}}),'bad')]});await p.evaluate(({STORE,raw})=>localStorage.setItem(STORE,raw),{STORE,raw});await p.reload();assert.equal(await p.evaluate(STORE=>localStorage.getItem(STORE),STORE),raw);assert.equal(await p.locator('#storageNotice').isVisible(),true);});
test('60 nested import fields and forged rollback are rejected without altering existing slot',async p=>{await seed(p);const before=await read(p);const bad=[fixture({diceType:'6"]<img src=x>'}),fixture({diceHistory:[{type:'D6',result:99}]}),fixture({log:[null]}),fixture({woundTask:{value:'<img>',source:'rest',stage:'fatigue',fatigue:[],deck:[]}}),fixture({combat:{base:10,wound:1,attempt:0,stage:'choose',modifier:null,adjusted:false,rollback:'{}'}}),fixture({challenge:{base:10,stage:'choose',modifier:null,adjusted:false,allowed:['H','D'],rollback:JSON.stringify(fixture({zones:{deck:['C13'],hand:[],fatigue:[],wound:[]}}))}})];for(const s of bad){await importData(p,s);assert.match(await p.locator('#status').innerText(),/Import failed/);assert.equal(await p.locator('[data-continue]').count(),1);assert.deepEqual(await read(p),before);}});
test('61 legacy missing pool and budget fields are derived without losing cards',async p=>{await seed(p);const s=fixture();delete s.pool;delete s.pointLimit;delete s.upgradePoints;delete s.inventory;delete s.diceType;delete s.diceHistory;await importData(p,s);assert.match(await p.locator('#status').innerText(),/imported successfully/);const id=await p.locator('[data-continue]').last().getAttribute('data-continue');const restored=await read(p,id);invariant(restored);assert.deepEqual(restored.zones,s.zones);assert.equal(restored.pointLimit,50);assert.equal(restored.upgradePoints,23);});
test('62 storage write failure stays visible across actions and retry saves unsaved state',async p=>{await load(p);await p.evaluate(()=>{window.originalSetItem=Storage.prototype.setItem;Storage.prototype.setItem=function(){throw Error('quota')}});await click(p,'[data-resource="Coin"][data-delta="1"]');assert.equal((await read(p)).res.Coin,8);await action(p,'heal');assert.equal(await p.locator('#storageNotice').isVisible(),true);const download=p.waitForEvent('download');await click(p,'#storageBackup');const d=await download;const backup=JSON.parse(fs.readFileSync(await d.path(),'utf8'));assert.equal(backup.slots[0].state.res.Coin,9);await p.evaluate(()=>Storage.prototype.setItem=window.originalSetItem);await click(p,'#storageRetry');assert.equal((await read(p)).res.Coin,9);assert.equal(await p.locator('#storageNotice').isVisible(),false);assert.match(await p.locator('#status').innerText(),/Progress saved/);});
test('63 exact-match optional recovery covers zero and one card in both encounter types',async p=>{for(const combatMode of [false,true])for(const count of [0,1]){await load(p);await random(p);if(combatMode){await combat(p,['H2','H3'],5);await click(p,'#combatResolve')}else{await challenge(p,['H2','H3'],5);await click(p,'#resolve')}if(count)await pick(p,['H2']);await click(p,combatMode?'#combatExact':'#finishExact');const s=await read(p);assert.equal(s.zones.fatigue.length,2-count);assert.equal(s.zones.hand.length,0);assert.equal(s.combat,null);assert.equal(s.challenge,null);invariant(s);}});
test('64 no-Supply Rest resumes through menu and persisted cancellation starts a fresh Rest',async p=>{await load(p,fixture({res:{Coin:8,Fate:4,Supply:0},zones:{deck:['H3'],hand:[],fatigue:['C5','H2'],wound:[]}}));await action(p,'rest');await click(p,'#restWoundStart');await pick(p,['C5']);await click(p,'#woundNext');await click(p,'#newGameTop');await click(p,'[data-continue="one"]');assert.equal(await p.locator('#target').count(),1);assert.equal(await p.locator('#restWoundStart').count(),0);await click(p,'#cancel');assert.equal((await read(p)).restWoundResolved,false);await p.reload();await click(p,'[data-continue="one"]');await action(p,'rest');assert.equal(await p.locator('#restWoundStart').count(),1);});
test('65 active combat and allocated wounds survive reload and retain safe Cancel',async p=>{await load(p);const before=await read(p);await random(p);await combat(p,['H1'],20,2);await click(p,'#combatResolve');await click(p,'#woundNext');const committed=await read(p);assert.equal(committed.woundTask.stage,'deck');await p.reload();await click(p,'[data-continue="one"]');assert.equal(await p.locator('#finishWound').count(),1);await click(p,'#cancelEncounter');assert.deepEqual(await read(p),before);});
test('66 v9 and v10 slot migrations preserve independent characters',async p=>{for(const key of ['quest-for-glory-v9-slots','quest-for-glory-v10-slots']){const original=fixture();await seed(p,[slot(original)],key);await click(p,'[data-continue="one"]');assert.deepEqual(await read(p),original);}});
test('67 numeric overflow is blocked for resource increments and Fate upgrades',async p=>{await load(p,fixture({res:{Coin:Number.MAX_SAFE_INTEGER,Fate:1,Supply:0},pointLimit:Number.MAX_SAFE_INTEGER,upgradePoints:Number.MAX_SAFE_INTEGER-27}));await click(p,'[data-resource="Coin"][data-delta="1"]');assert.equal((await read(p)).res.Coin,Number.MAX_SAFE_INTEGER);await action(p,'upgrade');await click(p,'#buyUpgrade');assert.equal((await read(p)).res.Fate,1);assert.equal((await read(p)).pointLimit,Number.MAX_SAFE_INTEGER);});
test('68 a dice label starts one 2D6 roll rather than a duplicate synthetic click',async p=>{await load(p);await p.evaluate(()=>{window.draws=0;Math.random=()=>{window.draws++;return .4}});await click(p,'#diceToggle');await click(p,'label:has(input[value="2d6"]) span');assert.equal(await p.evaluate(()=>window.draws),2);await p.waitForTimeout(750);assert.equal((await read(p)).diceHistory.length,1);});
test('69 character collapse defaults include Roll History and Inventory',async p=>{await seed(p,[slot(fixture(),'one'),slot(fixture(),'two')]);await click(p,'[data-continue="one"]');await click(p,'#inventoryToggle');await click(p,'#diceToggle');await click(p,'#diceHistoryToggle');await click(p,'#activityToggle');await click(p,'#newGameTop');await click(p,'[data-continue="two"]');for(const id of ['inventoryBody','diceBody','diceHistoryContent','activityBody'])assert.equal(await p.locator('#'+id).isVisible(),false);});

test('70 live add previews update failure, exact match and success without spending Fate',async p=>{for(const isCombat of [false,true]){await load(p);await random(p);if(isCombat)await combat(p,['H3'],5);else await challenge(p,['H3'],5);await click(p,isCombat?'#combatAdd':'#add');const before=await read(p);assert.match(await p.locator('#handAdjustmentPreview').innerText(),/Select a card/);for(const [id,total,outcome]of [['H1',4,'Failure'],['H2',5,'Success · Exact match'],['C5',8,'Success']]){await pick(p,[id]);const text=await p.locator('#handAdjustmentPreview').innerText();assert.ok(text.includes(`3 → ${total}`),text);assert.ok(text.includes(outcome),text);assert.match(text,/Total Challenge Value: 5/);assert.deepEqual(await read(p),before,'preview must not change saved cards, resources or logs');}await click(p,isCombat?'#combatApply':'#apply');const s=await read(p);assert.equal(s.zones.hand.reduce((n,id)=>n+Number(id.slice(1)),0),8);assert.equal(s.res.Fate,3);invariant(s);}});
test('71 live remove previews update success, exact match and failure before confirmation',async p=>{for(const isCombat of [false,true]){await load(p);await random(p);if(isCombat)await combat(p,['H2','H3','C5'],7);else await challenge(p,['H2','H3','C5'],7);await click(p,isCombat?'#combatRemove':'#remove');const before=await read(p);for(const [id,total,outcome]of [['H2',8,'Success'],['H3',7,'Success · Exact match'],['C5',5,'Failure']]){await pick(p,[id]);const text=await p.locator('#handAdjustmentPreview').innerText();assert.ok(text.includes(`10 → ${total}`),text);assert.match(text,/Total Challenge Value: 7/);assert.ok(text.includes(outcome),text);assert.deepEqual(await read(p),before);}await click(p,isCombat?'#combatApply':'#apply');const s=await read(p);assert.deepEqual(s.zones.hand,['H2','H3']);assert.equal(s.res.Fate,3);invariant(s);}});
test('72 preview respects Luck eligibility and face value; Back discards the preview',async p=>{await load(p,fixture({zones:{deck:['D1','D6','H3'],hand:[],fatigue:[],wound:[]}}));await random(p);await action(p,'challenge');await p.locator('#difficulty').fill('7');for(const suit of ['H','S','C'])await click(p,`[data-suit="${suit}"]`);await click(p,'#begin');await pick(p,['D1']);await click(p,'#commitChallenge');await click(p,'#add');assert.equal(await p.locator('#operation [data-card="H3"]').count(),0);const before=await read(p);await pick(p,['D6']);assert.match(await p.locator('#handAdjustmentPreview').innerText(),/1 → 7/);assert.match(await p.locator('#handAdjustmentPreview').innerText(),/\(\+6\)/);assert.match(await p.locator('#handAdjustmentPreview').innerText(),/Exact match/);await click(p,'#back');assert.equal(await p.locator('#handAdjustmentPreview').count(),0);assert.deepEqual(await read(p),before);await click(p,'#add');assert.match(await p.locator('#handAdjustmentPreview').innerText(),/Select a card/);});
test('73 combat retry preview uses reduced difficulty plus the revealed modifier',async p=>{await load(p);await random(p);await combat(p,['H1'],9);await click(p,'#combatResolve');await pick(p,['H1']);await click(p,'#woundNext');await click(p,'#combatRetry');await random(p,0);await pick(p,['H3']);await click(p,'#combatCommit');await click(p,'#combatRemove');await pick(p,['H3']);const text=await p.locator('#handAdjustmentPreview').innerText();assert.match(text,/3 → 0/);assert.match(text,/Total Challenge Value: 1/);assert.match(text,/Failure/);});
test('74 mobile touch selection updates the live preview without horizontal overflow',async(p,ctx,browser)=>{const c=await browser.newContext({viewport:{width:390,height:844},isMobile:true,hasTouch:true});try{const q=await c.newPage();await q.goto(p.url());await load(q);await random(q);await challenge(q,['H3'],5);await click(q,'#add');await q.locator('#operation [data-card="H2"]').tap();assert.match(await q.locator('#handAdjustmentPreview').innerText(),/3 → 5/);assert.match(await q.locator('#handAdjustmentPreview').innerText(),/Success · Exact match/);assert.ok(await q.evaluate(()=>document.documentElement.scrollWidth<=innerWidth));await q.screenshot({path:path.join(OUT,'v20-live-preview-mobile.png'),fullPage:true});}finally{await c.close()}});

test('75 purchase tip is one-time per character and remembered after cancel/reload',async p=>{await seed(p,[slot(fixture(),'one'),slot(fixture({characterName:'Other'}),'two')]);await click(p,'[data-continue="one"]');await click(p,'#inventoryToggle');await click(p,'#inventoryAdd');await p.locator('#inventoryPurchased').check();assert.equal(await p.locator('#inventoryPurchaseTip').isVisible(),true);assert.match(await p.locator('#inventoryPurchaseTip').innerText(),/deducted.*total Coin.*confirm/);assert.equal((await read(p)).res.Coin,8);await p.locator('#inventoryPurchased').uncheck();await p.locator('#inventoryPurchased').check();assert.equal(await p.locator('#inventoryPurchaseTip').isVisible(),false);await click(p,'#inventoryModalCancel');await p.reload();await click(p,'[data-continue="one"]');await click(p,'#inventoryToggle');await click(p,'#inventoryAdd');await p.locator('#inventoryPurchased').check();assert.equal(await p.locator('#inventoryPurchaseTip').isVisible(),false);await click(p,'#inventoryModalCancel');await click(p,'#newGameTop');await click(p,'[data-continue="two"]');await click(p,'#inventoryToggle');await click(p,'#inventoryAdd');await p.locator('#inventoryPurchased').check();assert.equal(await p.locator('#inventoryPurchaseTip').isVisible(),true);});
test('76 sale tip is independent and appears only for the first Sold checkbox',async p=>{await load(p,fixture({inventory:[{description:'Rope',keywords:'',baseValue:3},{description:'Torch',keywords:'',baseValue:1}],inventoryTipsSeen:{purchase:true}}));await click(p,'#inventoryToggle');await click(p,'[data-remove-item="0"]');await p.locator('#inventorySold').check();assert.equal(await p.locator('#inventorySaleTip').isVisible(),true);assert.match(await p.locator('#inventorySaleTip').innerText(),/added.*total Coin.*confirm/);assert.equal((await read(p)).res.Coin,8);await click(p,'#inventoryRemoveConfirm');assert.equal((await read(p)).res.Coin,11);await p.reload();await click(p,'[data-continue="one"]');await click(p,'#inventoryToggle');await click(p,'[data-remove-item="0"]');await p.locator('#inventorySold').check();assert.equal(await p.locator('#inventorySaleTip').isVisible(),false);assert.deepEqual((await read(p)).inventoryTipsSeen,{purchase:true,sale:true});});
test('77 Undo and encounter cancellation do not repeat already-seen inventory tips',async p=>{await load(p,fixture({inventory:[{description:'Rope',keywords:'',baseValue:1}]}));await click(p,'[data-resource="Coin"][data-delta="1"]');await click(p,'#inventoryToggle');await click(p,'#inventoryAdd');await p.locator('#inventoryPurchased').check();await click(p,'#inventoryModalCancel');await click(p,'#undo');assert.equal((await read(p)).res.Coin,8);assert.equal((await read(p)).inventoryTipsSeen.purchase,true);await random(p);await challenge(p);await click(p,'[data-remove-item="0"]');await p.locator('#inventorySold').check();assert.equal(await p.locator('#inventorySaleTip').isVisible(),true);await click(p,'#inventoryRemoveForm .secondary');await click(p,'#cancelEncounter');assert.deepEqual((await read(p)).inventoryTipsSeen,{purchase:true,sale:true});await click(p,'[data-remove-item="0"]');await p.locator('#inventorySold').check();assert.equal(await p.locator('#inventorySaleTip').isVisible(),false);});
test('78 inventory tips persist through JSON export/import and malformed preferences are rejected',async p=>{await seed(p,[slot(fixture({inventoryTipsSeen:{purchase:true,sale:true}}))]);const pending=p.waitForEvent('download');await click(p,'[data-export="one"]');const d=await pending;const raw=JSON.parse(fs.readFileSync(await d.path(),'utf8'));await importData(p,raw);const id=await p.locator('[data-continue]').last().getAttribute('data-continue');assert.deepEqual((await read(p,id)).inventoryTipsSeen,{purchase:true,sale:true});await importData(p,fixture({inventoryTipsSeen:{purchase:'yes'}}));assert.match(await p.locator('#status').innerText(),/Import failed/);assert.equal(await p.locator('[data-continue]').count(),2);await click(p,`[data-continue="${id}"]`);await click(p,'#inventoryToggle');await click(p,'#inventoryAdd');await p.locator('#inventoryPurchased').check();assert.equal(await p.locator('#inventoryPurchaseTip').isVisible(),false);});

async function defineEnemy(p,{name='Enemy',base=5,woundValue=1,fate=1,coin=0,item=null}={}){
 await action(p,'combat');await p.locator('#enemyName').fill(name);await p.locator('#combatDifficulty').fill(String(base));await p.locator('#combatWound').fill(String(woundValue));await p.locator('#enemyFateReward').fill(String(fate));await p.locator('#enemyCoinReward').fill(String(coin));
 if(item){await p.locator('#enemyHasItem').check();await p.locator('#enemyItemDescription').fill(item.description);await p.locator('#enemyItemKeywords').fill(item.keywords||'');await p.locator('#enemyItemValue').fill(String(item.baseValue))}await click(p,'#startCombat');
}
async function adjust(p,isCombat,adding,id){await click(p,isCombat?(adding?'#combatAdd':'#combatRemove'):(adding?'#add':'#remove'));await pick(p,[id]);await click(p,isCombat?'#combatApply':'#apply');}
const inventoryEight=()=>Array.from({length:8},(_,i)=>({description:'Item '+i,keywords:'original',baseValue:i+1}));
const rewardItem={description:'Enchanted Sword',keywords:'weapon, magic',baseValue:12};

test('79 repeated Fate additions/removals share costs 1, 2, 4, 8 in each action',async p=>{for(const isCombat of [false,true]){await load(p,fixture({res:{Coin:8,Fate:15,Supply:2}}));await random(p);if(isCombat)await combat(p,['H3'],30);else await challenge(p,['H3'],30);for(const [adding,id,remaining,next]of [[true,'H2',14,2],[false,'H2',12,4],[true,'H1',8,8],[false,'H1',0,16]]){await adjust(p,isCombat,adding,id);const s=await read(p);assert.equal(s.res.Fate,remaining);assert.match(await p.locator(isCombat?'#combatAdd':'#add').innerText(),new RegExp(next+' Fate'));invariant(s);}const s=await read(p);assert.equal((isCombat?s.combat:s.challenge).adjustmentsUsed,4);assert.equal(await p.locator(isCombat?'#combatAdd':'#add').isDisabled(),true);assert.equal(await p.locator(isCombat?'#combatRemove':'#remove').isDisabled(),true);}});
test('80 initial hand has at most five cards; paid additions can exceed five',async p=>{for(const isCombat of [false,true]){await load(p);await random(p);if(isCombat){await defineEnemy(p,{base:30})}else{await action(p,'challenge');await click(p,'#begin')}const first=['H1','H2','H3','S4','C5'];await pick(p,first);assert.equal(await p.locator('#operation [data-card="D6"]').isDisabled(),true);await pick(p,['H1']);assert.equal(await p.locator('#operation [data-card="D6"]').isEnabled(),true);await pick(p,['H1']);await click(p,isCombat?'#combatCommit':'#commitChallenge');assert.equal((await read(p)).zones.hand.length,5);await adjust(p,isCombat,true,'D6');const s=await read(p);assert.equal(s.zones.hand.length,6);assert.equal(s.res.Fate,3);invariant(s);}});
test('81 doubling cost survives reload, Back does not charge, Cancel restores the complete state',async p=>{for(const isCombat of [false,true]){await load(p,fixture({res:{Coin:8,Fate:12,Supply:2}}));const before=await read(p);await random(p);if(isCombat)await combat(p);else await challenge(p);await adjust(p,isCombat,true,'H2');await p.reload();await click(p,'[data-continue="one"]');assert.match(await p.locator(isCombat?'#combatAdd':'#add').innerText(),/2 Fate/);await click(p,isCombat?'#combatAdd':'#add');await pick(p,['D6']);await click(p,isCombat?'#combatBack':'#back');assert.equal((await read(p)).res.Fate,11);await adjust(p,isCombat,false,'H2');assert.equal((await read(p)).res.Fate,9);await click(p,'#cancelEncounter');assert.deepEqual(await read(p),before);}});
test('82 combat retry resets the next adjustment cost to one and preserves enemy rewards',async p=>{await load(p,fixture({res:{Coin:8,Fate:20,Supply:2}}));await random(p);await defineEnemy(p,{name:'Troll',base:30,fate:3,coin:2});await pick(p,['H3']);await click(p,'#combatCommit');await adjust(p,true,true,'H2');await adjust(p,true,false,'H2');await click(p,'#combatResolve');await pick(p,['H3']);await click(p,'#woundNext');await click(p,'#combatRetry');assert.equal((await read(p)).combat.adjustmentsUsed,0);assert.equal((await read(p)).combat.enemy.name,'Troll');assert.equal((await read(p)).combat.enemy.fateReward,3);await pick(p,['H1']);await click(p,'#combatCommit');assert.match(await p.locator('#combatAdd').innerText(),/1 Fate/);assert.match(await p.locator('#operation').innerText(),/Base challenge 28/);});
test('83 enemy prompt defaults and cancellation leave the character unchanged',async p=>{await load(p);const before=await read(p);await action(p,'combat');assert.equal(await p.locator('#enemySetupModal').isVisible(),true);for(const [id,value]of Object.entries({enemyName:'Enemy',combatDifficulty:'5',combatWound:'1',enemyFateReward:'1',enemyCoinReward:'0'}))assert.equal(await p.locator('#'+id).inputValue(),value);assert.equal(await p.locator('#enemyHasItem').isChecked(),false);await click(p,'#enemySetupCancel');assert.deepEqual(await read(p),before);await action(p,'combat');await click(p,'#startCombat');assert.deepEqual((await read(p)).combat.enemy,{name:'Enemy',fateReward:1,coinReward:0,itemReward:null});});
test('84 ordinary victory adds configured Fate, Coin and inventory item exactly once',async p=>{await load(p);await random(p);await defineEnemy(p,{name:'Goblin',base:4,fate:3,coin:7,item:rewardItem});await pick(p,['C5']);await click(p,'#combatCommit');await click(p,'#combatResolve');let s=await read(p);assert.equal(s.combat,null);assert.equal(s.res.Fate,7);assert.equal(s.res.Coin,15);assert.deepEqual(s.inventory,[rewardItem]);invariant(s);await p.reload();await click(p,'[data-continue="one"]');s=await read(p);assert.equal(s.res.Fate,7);assert.equal(s.res.Coin,15);assert.deepEqual(s.inventory,[rewardItem]);assert.equal(s.log.filter(e=>e.message.includes('Defeated Goblin')).length,1);});
test('85 exact-match victory grants rewards only after the recovery choice',async p=>{await load(p);await random(p);await defineEnemy(p,{base:5,fate:2,coin:4,item:rewardItem});await pick(p,['H2','H3']);await click(p,'#combatCommit');await click(p,'#combatResolve');assert.equal((await read(p)).res.Fate,4);assert.equal((await read(p)).inventory.length,0);await pick(p,['H2']);await click(p,'#combatExact');const s=await read(p);assert.equal(s.res.Fate,6);assert.equal(s.res.Coin,12);assert.deepEqual(s.inventory,[rewardItem]);assert.ok(s.zones.deck.includes('H2'));invariant(s);});
test('86 failed combat and fleeing do not grant configured rewards',async p=>{await load(p);await random(p);await defineEnemy(p,{base:30,fate:10,coin:10,item:rewardItem});await pick(p,['H1']);await click(p,'#combatCommit');await click(p,'#combatResolve');await pick(p,['H1']);await click(p,'#woundNext');let s=await read(p);assert.equal(s.res.Fate,4);assert.equal(s.res.Coin,8);assert.equal(s.inventory.length,0);await click(p,'#combatFlee');s=await read(p);assert.equal(s.res.Fate,2);assert.equal(s.res.Coin,8);assert.equal(s.inventory.length,0);});
test('87 full inventory decline retains all existing items and resource rewards',async p=>{await load(p,fixture({inventory:inventoryEight()}));await random(p);await defineEnemy(p,{base:4,fate:2,coin:3,item:rewardItem});await pick(p,['C5']);await click(p,'#combatCommit');await click(p,'#combatResolve');assert.equal(await p.locator('#combatRewardModal').isVisible(),true);assert.equal((await read(p)).combat.rewardsGranted,true);assert.equal((await read(p)).res.Coin,11);await click(p,'#rewardDecline');const s=await read(p);assert.equal(s.combat,null);assert.deepEqual(s.inventory,inventoryEight());assert.equal(s.res.Coin,11);assert.equal(s.res.Fate,6);});
test('88 full inventory replacement lists all items and discards only the selected item without sale proceeds',async p=>{await load(p,fixture({inventory:inventoryEight()}));await random(p);await defineEnemy(p,{base:4,coin:2,item:rewardItem});await pick(p,['C5']);await click(p,'#combatCommit');await click(p,'#combatResolve');await click(p,'#rewardReplaceYes');assert.equal(await p.locator('#rewardChoiceList input').count(),8);assert.equal(await p.locator('#rewardReplaceConfirm').isDisabled(),true);await p.locator('input[name="rewardDiscard"][value="3"]').check();await click(p,'#rewardReplaceConfirm');const s=await read(p);assert.equal(s.inventory.length,8);assert.deepEqual(s.inventory[3],rewardItem);assert.deepEqual(s.inventory.filter((_,i)=>i!==3),inventoryEight().filter((_,i)=>i!==3));assert.equal(s.res.Coin,10);assert.equal(s.res.Fate,5);assert.equal(s.combat,null);});
test('89 pending reward survives reload and JSON transfer without duplicating resources',async p=>{await load(p,fixture({inventory:inventoryEight()}));await random(p);await defineEnemy(p,{name:'Dragon',base:4,fate:3,coin:5,item:rewardItem});await pick(p,['C5']);await click(p,'#combatCommit');await click(p,'#combatResolve');await p.reload();await click(p,'[data-continue="one"]');assert.equal((await read(p)).res.Fate,7);assert.equal((await read(p)).res.Coin,13);assert.equal(await p.locator('#combatRewardModal').isVisible(),true);await click(p,'#rewardReplaceYes');await p.reload();const pending=p.waitForEvent('download');await click(p,'[data-export="one"]');const d=await pending;const raw=JSON.parse(fs.readFileSync(await d.path(),'utf8'));await importData(p,raw);assert.match(await p.locator('#status').innerText(),/imported successfully/);const id=await p.locator('[data-continue]').last().getAttribute('data-continue');await click(p,`[data-continue="${id}"]`);assert.equal(await p.locator('#rewardReplacement').isVisible(),true);await p.locator('input[name="rewardDiscard"][value="0"]').check();await click(p,'#rewardReplaceConfirm');const s=await read(p,id);assert.equal(s.res.Fate,7);assert.equal(s.res.Coin,13);assert.deepEqual(s.inventory[0],rewardItem);assert.equal(s.log.filter(e=>e.message.includes('Defeated Dragon')).length,1);});
test('90 Undo of victory/replacement restores awards consistently without duplication',async p=>{await load(p,fixture({inventory:inventoryEight()}));await random(p);await defineEnemy(p,{base:4,fate:2,coin:3,item:rewardItem});await pick(p,['C5']);await click(p,'#combatCommit');await click(p,'#combatResolve');await click(p,'#rewardReplaceYes');await p.locator('input[name="rewardDiscard"][value="0"]').check();await click(p,'#rewardReplaceConfirm');await click(p,'#undo');let s=await read(p);assert.equal(s.combat.stage,'reward');assert.equal(s.res.Fate,6);assert.equal(s.res.Coin,11);assert.deepEqual(s.inventory,inventoryEight());await click(p,'#rewardReplacementBack');await click(p,'#rewardDecline');s=await read(p);assert.equal(s.res.Coin,11);assert.equal(s.res.Fate,6);});
test('91 enemy and reward fields reject invalid values and enforce combined text length',async p=>{await load(p);await action(p,'combat');const before=await read(p);for(const [id,value]of [['combatWound','0'],['enemyFateReward','-1'],['enemyCoinReward','1.5']]){await p.locator('#'+id).fill(value);await click(p,'#startCombat');assert.equal(await p.locator('#enemySetupModal').isVisible(),true);assert.ok((await p.locator('#enemySetupError').innerText()).length>0);await p.locator('#'+id).fill(id==='combatWound'?'1':'0')}await p.locator('#enemyHasItem').check();await click(p,'#startCombat');assert.equal(await p.locator('#enemySetupModal').isVisible(),true);await p.locator('#enemyItemDescription').fill('a'.repeat(290));await p.locator('#enemyItemKeywords').fill('b'.repeat(30));assert.equal((await p.locator('#enemyItemDescription').inputValue()).length+(await p.locator('#enemyItemKeywords').inputValue()).length,300);assert.deepEqual(await read(p),before);await click(p,'#startCombat');assert.equal((await read(p)).combat.enemy.itemReward.description.length,290);});
test('92 malformed enemy rewards and adjustment counters are rejected on import',async p=>{await seed(p);const oldCombat={base:5,wound:1,attempt:0,stage:'choose',modifier:null,adjusted:false};for(const patch of [{enemy:{name:'Bad',fateReward:-1,coinReward:0,itemReward:null}},{enemy:{name:'Bad',fateReward:1,coinReward:0,itemReward:{description:'x',keywords:'',baseValue:-1}}},{adjustmentsUsed:54},{adjustmentsUsed:1},{rewardsGranted:true}]){await importData(p,fixture({combat:{...oldCombat,...patch}}));assert.match(await p.locator('#status').innerText(),/Import failed/);assert.equal(await p.locator('[data-continue]').count(),1);}});
test('93 V18 encounters migrate previous Fate usage without retroactive enemy rewards',async p=>{const s=fixture({zones:{deck:['H1','H2','S4','C5','D6'],hand:['H3'],fatigue:[],wound:[]},combat:{base:2,wound:1,attempt:0,stage:'decide',modifier:0,adjusted:true}});await load(p,s);assert.match(await p.locator('#combatAdd').innerText(),/2 Fate/);await click(p,'#combatResolve');const restored=await read(p);assert.equal(restored.combat,null);assert.equal(restored.res.Fate,4);assert.equal(restored.res.Coin,8);invariant(restored);});
test('94 rewards that overflow resources remain pending until safely collectible',async p=>{await load(p,fixture({res:{Coin:Number.MAX_SAFE_INTEGER,Fate:4,Supply:2}}));await random(p);await defineEnemy(p,{base:4,fate:3,coin:1});await pick(p,['C5']);await click(p,'#combatCommit');await click(p,'#combatResolve');let s=await read(p);assert.equal(s.combat.stage,'reward');assert.equal(s.combat.rewardsGranted,false);assert.equal(s.res.Fate,4);await click(p,'[data-resource="Coin"][data-delta="-1"]');await click(p,'#collectCombatRewards');s=await read(p);assert.equal(s.res.Coin,Number.MAX_SAFE_INTEGER);assert.equal(s.res.Fate,7);assert.equal(s.combat,null);});
