test('97 mobile enemy and full-inventory reward dialogs remain usable and text is escaped',async(p,ctx,browser)=>{const c=await browser.newContext({viewport:{width:320,height:844},isMobile:true,hasTouch:true});try{const q=await c.newPage();await q.goto(p.url());await load(q,fixture({inventory:inventoryEight()}));await random(q);await action(q,'combat');assert.ok(await q.evaluate(()=>document.documentElement.scrollWidth<=innerWidth));const cancel=await q.locator('#enemySetupCancel').boundingBox(),begin=await q.locator('#startCombat').boundingBox();assert.ok(Math.abs(cancel.y-begin.y)<1,'enemy setup buttons must align');await q.screenshot({path:path.join(OUT,'v20-enemy-setup-mobile.png')});await q.locator('#enemyName').fill('<img src=x onerror="window.injected=true">'+'X'.repeat(40));await q.locator('#combatDifficulty').fill('4');await q.locator('#enemyHasItem').check();await q.locator('#enemyItemDescription').fill('Treasure');await click(q,'#startCombat');await pick(q,['C5']);await click(q,'#combatCommit');await click(q,'#combatResolve');assert.equal(await q.locator('#combatRewardModal').isVisible(),true);assert.equal(await q.evaluate(()=>!!window.injected),false);await q.locator('#rewardReplaceYes').tap();await q.locator('input[name="rewardDiscard"][value="7"]').check();await q.screenshot({path:path.join(OUT,'v20-reward-mobile.png')});assert.ok(await q.evaluate(()=>document.documentElement.scrollWidth<=innerWidth));await q.locator('#rewardReplaceConfirm').tap();assert.equal((await read(q)).inventory[7].description,'Treasure');}finally{await c.close()}});
test('98 full inventory without an item reward finishes normally and Game Over grants no reward',async p=>{await load(p,fixture({inventory:inventoryEight()}));await random(p);await combat(p,['C5'],4);await click(p,'#combatResolve');assert.equal((await read(p)).combat,null);assert.equal(await p.locator('#combatRewardModal').isVisible(),false);await load(p,fixture({zones:{deck:['H1'],hand:[],fatigue:[],wound:[]}}));await random(p);await defineEnemy(p,{base:30,fate:10,coin:10,item:rewardItem});await pick(p,['H1']);await click(p,'#combatCommit');await click(p,'#combatResolve');await pick(p,['H1']);await click(p,'#woundNext');const s=await read(p);assert.equal(s.dead,true);assert.equal(s.res.Fate,4);assert.equal(s.res.Coin,8);assert.equal(s.inventory.length,0);});

