test('102 an expanded paid hand and the next Fate cost survive reload',async p=>{await load(p,fixture({zones:{deck:['H1','H2','H3','H4','H5','H6','H7'],hand:[],fatigue:[],wound:[]}}));await random(p);await challenge(p,['H1','H2','H3','H4','H5'],30);await adjust(p,false,true,'H6');await p.reload();await click(p,'[data-continue="one"]');assert.equal((await read(p)).zones.hand.length,6);assert.match(await p.locator('#add').innerText(),/2 Fate/);await adjust(p,false,true,'H7');const s=await read(p);assert.equal(s.zones.hand.length,7);assert.equal(s.res.Fate,1);assert.equal(s.challenge.adjustmentsUsed,2);invariant(s);});
test('103 exponential adjustment costs stop safely at the numeric limit',async p=>{const s=fixture({res:{Coin:8,Fate:Number.MAX_SAFE_INTEGER,Supply:2},zones:{deck:['H1','H2','S4','C5','D6'],hand:['H3'],fatigue:[],wound:[]},challenge:{base:5,modifier:0,stage:'decide',adjusted:true,adjustmentsUsed:52,allowed:['H','S','C','D']}});await load(p,s);await adjust(p,false,true,'H2');const restored=await read(p);assert.equal(restored.res.Fate,Number.MAX_SAFE_INTEGER-2**52);assert.equal(restored.challenge.adjustmentsUsed,53);assert.equal(await p.locator('#add').isDisabled(),true);assert.equal(await p.locator('#remove').isDisabled(),true);assert.match(await p.locator('#operation').innerText(),/No further Fate adjustments/);});
