test('105 new dialogs keep keyboard focus inside and Escape never silently discards a reward',async p=>{await load(p,fixture({inventory:inventoryEight()}));const before=await read(p);await action(p,'combat');assert.equal(await p.locator(':focus').getAttribute('id'),'enemyName');await p.keyboard.press('Shift+Tab');assert.equal(await p.locator(':focus').getAttribute('id'),'startCombat');await p.keyboard.press('Tab');assert.equal(await p.locator(':focus').getAttribute('id'),'enemyName');await p.keyboard.press('Escape');assert.equal(await p.locator('#enemySetupModal').isVisible(),false);assert.deepEqual(await read(p),before);await random(p);await defineEnemy(p,{base:4,item:rewardItem});await pick(p,['C5']);await click(p,'#combatCommit');await click(p,'#combatResolve');assert.equal(await p.locator(':focus').getAttribute('id'),'rewardDecline');await p.keyboard.press('Shift+Tab');assert.equal(await p.locator(':focus').getAttribute('id'),'rewardReplaceYes');await click(p,'#rewardReplaceYes');await p.keyboard.press('Escape');assert.equal(await p.locator('#rewardQuestion').isVisible(),true);await p.keyboard.press('Escape');assert.equal(await p.locator('#combatRewardModal').isVisible(),true);assert.equal((await read(p)).combat.stage,'reward');await click(p,'#rewardDecline');});
test('106 the V19 enemy, paid adjustment and victory reward flow works fully offline',async(p,ctx,browser)=>{const c=await browser.newContext({offline:true});try{const q=await c.newPage(),origin=new URL(p.url()).origin,external=[];q.setDefaultTimeout(2500);await c.route('**/*',r=>{if(new URL(r.request().url()).origin===origin)return r.fulfill({status:200,contentType:'text/html',body:fs.readFileSync(APP_FILE)});external.push(r.request().url());return r.abort()});await q.goto(origin);await load(q);await random(q);await defineEnemy(q,{name:'Offline Foe',base:4,fate:2,coin:3,item:rewardItem});await pick(q,['H3']);await click(q,'#combatCommit');await adjust(q,true,true,'C5');await click(q,'#combatResolve');const s=await read(q);assert.equal(s.res.Fate,5);assert.equal(s.res.Coin,11);assert.deepEqual(s.inventory,[rewardItem]);assert.equal(s.combat,null);await q.evaluate(()=>document.fonts.ready);assert.equal(await q.evaluate(()=>[...document.fonts].find(f=>f.family==='RighteousEmbedded').status),'loaded');assert.deepEqual(external,[]);invariant(s);}finally{await c.close()}});

async function manualAmount(p,key,amount,{remove=false,confirm=true}={}){await click(p,key==='Round'?'#roundDisplay':`[data-adjust-resource="${key}"]`);if(remove)await click(p,'#adjustRemove');await p.locator('#adjustAmount').fill(String(amount));if(confirm)await click(p,'#adjustConfirm');}

test('107 modifier-adjusted Challenge Value floors at one in both action types and previews',async p=>{for(const isCombat of [false,true]){await load(p);await random(p,0);if(isCombat)await combat(p,['H1'],3);else await challenge(p,['H1'],3);await click(p,isCombat?'#combatAdd':'#add');await pick(p,['H2']);assert.match(await p.locator('#handAdjustmentPreview').innerText(),/Total Challenge Value: 1/);await click(p,isCombat?'#combatBack':'#back');await click(p,isCombat?'#combatResolve':'#resolve');assert.equal(await p.locator(isCombat?'#combatExact':'#finishExact').count(),1);await click(p,isCombat?'#combatExact':'#finishExact');assert.equal((await read(p)).dead,false);}});
test('108 setup minimum and combat retry base both remain one or higher',async p=>{await load(p);await action(p,'challenge');await p.locator('#difficulty').fill('0');await click(p,'#begin');assert.equal((await read(p)).challenge,null);assert.equal(await p.locator('#difficulty').getAttribute('min'),'1');await action(p,'combat');await p.locator('#combatDifficulty').fill('0');await click(p,'#startCombat');assert.equal(await p.locator('#enemySetupModal').isVisible(),true);assert.equal((await read(p)).combat,null);await click(p,'#enemySetupCancel');await load(p,fixture({combat:{base:2,wound:1,attempt:5,stage:'afterFail',modifier:0,adjusted:false}}));assert.match(await p.locator('#operation').innerText(),/Base challenge 1/);assert.match(await p.locator('#combatRetry').innerText(),/difficulty 1/);await click(p,'#combatRetry');assert.match(await p.locator('#operation').innerText(),/Base challenge 1/);await random(p,0);await pick(p,['H1']);await click(p,'#combatCommit');await click(p,'#combatResolve');assert.equal(await p.locator('#combatExact').count(),1);});
test('109 legacy zero base and unfinished zero-value exact matches migrate without granting a false success',async p=>{await load(p,fixture({challenge:{base:0,modifier:-6,stage:'decide',adjusted:false,allowed:['H','S','C','D']}}));assert.match(await p.locator('#operation').innerText(),/Final challenge 1/);await load(p,fixture({challenge:{base:6,modifier:-6,stage:'exact',adjusted:true,allowed:['H','S','C','D']}}));assert.equal(await p.locator('#finishExact').count(),0);assert.match(await p.locator('#operation').innerText(),/Currently unsuccessful/);});
test('110 initial hand text is removed while the five-card limit and paid additions remain',async p=>{for(const combatMode of [false,true]){await load(p);if(combatMode)await defineEnemy(p);else{await action(p,'challenge');await click(p,'#begin')}assert.doesNotMatch(await p.locator('#operation').innerText(),/Paid Fate additions after the modifier may exceed 5/);await pick(p,['H1','H2','H3','S4','C5']);assert.equal(await p.locator('#operation [data-card="D6"]').isDisabled(),true);await random(p);await click(p,combatMode?'#combatCommit':'#commitChallenge');await adjust(p,combatMode,true,'D6');assert.equal((await read(p)).zones.hand.length,6);}});
test('111 Round begins at zero and sits between the character banner and Resources',async p=>{await click(p,'#createCharacter');await click(p,'#setupCards [data-card="H3"]');await click(p,'#startGame');assert.equal(await p.locator('#roundNumber').innerText(),'0');const order=await p.evaluate(()=>document.querySelector('.character-banner').getBoundingClientRect().bottom<=document.querySelector('#roundDisplay').getBoundingClientRect().top&&document.querySelector('#roundDisplay').getBoundingClientRect().bottom<document.querySelector('#resourcesPanel').getBoundingClientRect().top);assert.equal(order,true);const all=await p.evaluate(STORE=>JSON.parse(localStorage.getItem(STORE)).slots,STORE);assert.equal(all[0].state.round,0);});
test('112 each completed Rest advances Round once and Undo restores cards, Supply and Round',async p=>{await load(p,fixture({zones:{deck:['H3'],hand:[],fatigue:['H1','H2'],wound:[]}}));for(const [id,n]of [['H1',1],['H2',2]]){await action(p,'rest');await p.locator('#target').fill(String(n));await pick(p,[id]);await click(p,'#commit');assert.equal((await read(p)).round,n)}assert.equal((await read(p)).res.Supply,0);await click(p,'#undo');const s=await read(p);assert.equal(s.round,1);assert.equal(s.res.Supply,1);assert.deepEqual(s.zones.fatigue,['H2']);await p.reload();await click(p,'[data-continue="one"]');assert.equal(await p.locator('#roundNumber').innerText(),'1');});
test('113 no-Supply Rest advances Round only after recovery; cancellation and fatal wounds do not',async p=>{for(const complete of [true,false]){await load(p,fixture({res:{Coin:8,Fate:4,Supply:0},zones:{deck:['H3'],hand:[],fatigue:['C5','H2'],wound:[]}}));await action(p,'rest');await click(p,'#restWoundStart');await pick(p,['C5']);await click(p,'#woundNext');assert.equal((await read(p)).round,0);if(complete){await p.locator('#target').fill('2');await pick(p,['H2']);await click(p,'#commit');assert.equal((await read(p)).round,1)}else{await click(p,'#cancel');assert.equal((await read(p)).round,0)}}await load(p,fixture({res:{Coin:8,Fate:4,Supply:0},zones:{deck:['H1'],hand:[],fatigue:[],wound:[]}}));await action(p,'rest');await click(p,'#restWoundStart');await click(p,'#woundNext');await click(p,'#finishWound');assert.equal((await read(p)).dead,true);assert.equal((await read(p)).round,0);});
test('114 Round editor supports Add/Remove, preview, cancel, reload and nonnegative bounds',async p=>{await load(p);await manualAmount(p,'Round',5,{confirm:false});assert.equal(await p.locator('#adjustPreview').innerText(),'New total: 5');await click(p,'#adjustConfirm');assert.equal((await read(p)).round,5);await manualAmount(p,'Round',2,{remove:true});assert.equal((await read(p)).round,3);assert.match((await read(p)).log[0].message,/Round -2/);await manualAmount(p,'Round',7,{confirm:false});await click(p,'#adjustCancel');assert.equal((await read(p)).round,3);await manualAmount(p,'Round',4,{remove:true,confirm:false});assert.equal(await p.locator('#adjustConfirm').isDisabled(),true);await p.keyboard.press('Escape');await p.reload();await click(p,'[data-continue="one"]');assert.equal(await p.locator('#roundNumber').innerText(),'3');});
test('115 Round is independent per character and survives export/import; invalid counters are rejected',async p=>{await seed(p,[slot(fixture(),'one'),slot(fixture(),'two')]);await click(p,'[data-continue="one"]');await manualAmount(p,'Round',12);assert.equal((await read(p,'two')).round,0);await click(p,'#newGameTop');const download=p.waitForEvent('download');await click(p,'[data-export="one"]');const d=await download,raw=JSON.parse(fs.readFileSync(await d.path(),'utf8'));assert.equal(raw.character.round,12);await importData(p,raw);assert.equal(await p.locator('[data-continue]').count(),3);for(const round of [-1,1.5,'2',Number.MAX_SAFE_INTEGER+1]){await importData(p,fixture({round}));assert.match(await p.locator('#status').innerText(),/Import failed/);assert.equal(await p.locator('[data-continue]').count(),3)}const legacy=fixture();delete legacy.round;await importData(p,legacy);const id=await p.locator('[data-continue]').last().getAttribute('data-continue');assert.equal((await read(p,id)).round,0);});
test('116 maximum Round blocks Rest before costs or wounds and can be decreased manually',async p=>{await load(p,fixture({round:Number.MAX_SAFE_INTEGER,res:{Coin:8,Fate:4,Supply:0},zones:{deck:['H3'],hand:[],fatigue:['C5'],wound:[]}}));const before=await read(p);await action(p,'rest');assert.match(await p.locator('#status').innerText(),/Round limit/);assert.deepEqual(await read(p),before);assert.equal(await p.locator('#restWoundStart').count(),0);await manualAmount(p,'Round',1,{remove:true});assert.equal((await read(p)).round,Number.MAX_SAFE_INTEGER-1);});
test('117 all resource totals open Add/Remove dialogs and update values and activity',async p=>{await load(p);for(const [key,start]of [['Coin',8],['Fate',4],['Supply',2]]){await manualAmount(p,key,5,{confirm:false});assert.equal(await p.locator('#adjustPreview').innerText(),'New total: '+(start+5));await click(p,'#adjustConfirm');assert.equal((await read(p)).res[key],start+5);await manualAmount(p,key,3,{remove:true});assert.equal((await read(p)).res[key],start+2);assert.match((await read(p)).log[0].message,new RegExp(key+' -3'));assert.equal(await p.locator(':focus').getAttribute('data-adjust-resource'),key)}});
test('118 custom resource changes reject empty, fractional, negative, excessive and overflow amounts without mutations',async p=>{await load(p);const before=await read(p);await click(p,'[data-adjust-resource="Coin"]');for(const amount of ['', '0','-1','1.5',String(Number.MAX_SAFE_INTEGER)]){await p.locator('#adjustAmount').fill(amount);assert.equal(await p.locator('#adjustConfirm').isDisabled(),true);assert.deepEqual(await read(p),before)}await click(p,'#adjustRemove');await p.locator('#adjustAmount').fill('9');assert.equal(await p.locator('#adjustConfirm').isDisabled(),true);await click(p,'#adjustCancel');assert.deepEqual(await read(p),before);assert.equal(await p.locator('#undo').isDisabled(),true);});
test('119 all sections collapse with expanded primary defaults and always-visible title, character and Round',async p=>{await load(p);for(const [toggle,body]of [['resourcesToggle','resourcesBody'],['cardZonesToggle','cardZonesBody'],['actionsToggle','actionsBody']]){assert.equal(await p.locator('#'+body).isVisible(),true);assert.equal(await p.locator('#'+toggle).getAttribute('aria-expanded'),'true');await click(p,'#'+toggle);assert.equal(await p.locator('#'+body).isVisible(),false);assert.equal(await p.locator('#'+toggle).getAttribute('aria-expanded'),'false')}for(const body of ['inventoryBody','diceBody','diceHistoryContent','activityBody'])assert.equal(await p.locator('#'+body).isVisible(),false);for(const selector of ['header h1','#characterHeading','#moduleHeading','#roundDisplay'])assert.equal(await p.locator(selector).isVisible(),true);await manualAmount(p,'Round',2);for(const body of ['resourcesBody','cardZonesBody','actionsBody'])assert.equal(await p.locator('#'+body).isVisible(),false);});
test('120 collapsing active Actions preserves selection and cancellation restores manual counter changes',async p=>{await load(p);const before=await read(p);await action(p,'challenge');await click(p,'#begin');await pick(p,['H3']);await click(p,'#actionsToggle');await manualAmount(p,'Round',4);await click(p,'[data-resource="Coin"][data-delta="1"]');await click(p,'#actionsToggle');assert.equal(await p.locator('#operation [data-card="H3"]').getAttribute('class').then(x=>x.includes('selected')),true);assert.equal(await p.locator('#commitChallenge').isEnabled(),true);await click(p,'#cancelEncounter');assert.deepEqual(await read(p),before);});
test('121 section defaults reset on character entry without leaking collapsed state',async p=>{await seed(p,[slot(fixture(),'one'),slot(fixture(),'two')]);await click(p,'[data-continue="one"]');for(const id of ['resourcesToggle','cardZonesToggle','actionsToggle','inventoryToggle','diceToggle','activityToggle'])await click(p,'#'+id);await click(p,'#newGameTop');await click(p,'[data-continue="two"]');for(const body of ['resourcesBody','cardZonesBody','actionsBody'])assert.equal(await p.locator('#'+body).isVisible(),true);for(const body of ['inventoryBody','diceBody','activityBody'])assert.equal(await p.locator('#'+body).isVisible(),false);});
test('122 applied manual wounds shake the screen with a red overlay for half a second without extra state changes',async p=>{await load(p,fixture({zones:{deck:['H3'],hand:[],fatigue:['C5','H2'],wound:[]}}));await action(p,'wound');await p.locator('#woundValue').fill('5');await click(p,'#beginWound');await pick(p,['C5']);assert.equal(await p.locator('#woundOverlay').evaluate(e=>e.classList.contains('active')),false);await click(p,'#woundNext');assert.equal(await p.locator('main').evaluate(e=>e.classList.contains('wound-shake')),true);assert.equal(await p.locator('#woundOverlay').evaluate(e=>getComputedStyle(e).animationDuration),'0.5s');const saved=await read(p);assert.deepEqual(saved.zones.wound,['C5']);await p.waitForTimeout(650);assert.equal(await p.locator('#woundOverlay').evaluate(e=>e.classList.contains('active')),false);assert.equal(await p.locator('main').evaluate(e=>e.classList.contains('wound-shake')),false);assert.deepEqual(await read(p),saved);});
test('123 combat and no-Supply Rest wounds trigger the same effect, which does not replay on reload',async p=>{await load(p);await random(p);await combat(p,['H1'],30);await click(p,'#combatResolve');await pick(p,['H1']);await click(p,'#woundNext');assert.equal(await p.locator('#woundOverlay').evaluate(e=>e.classList.contains('active')),true);await p.reload();await click(p,'[data-continue="one"]');assert.equal(await p.locator('#woundOverlay').evaluate(e=>e.classList.contains('active')),false);await load(p,fixture({res:{Coin:8,Fate:4,Supply:0},zones:{deck:['H3'],hand:[],fatigue:['C5','H2'],wound:[]}}));await action(p,'rest');await click(p,'#restWoundStart');await pick(p,['C5']);await click(p,'#woundNext');assert.equal(await p.locator('#woundOverlay').evaluate(e=>e.classList.contains('active')),true);assert.equal((await read(p)).round,0);});
test('124 victory totals save immediately while Coin and Fate count up and shake visually',async p=>{await load(p);await random(p);await defineEnemy(p,{base:4,fate:20,coin:100});await pick(p,['C5']);await click(p,'#combatCommit');await click(p,'#combatResolve');const saved=await read(p);assert.equal(saved.res.Coin,108);assert.equal(saved.res.Fate,24);assert.equal(await p.locator('.resource-reward').count(),2);assert.equal(await p.locator('[data-resource-box="Supply"]').evaluate(e=>e.classList.contains('resource-reward')),false);const shown=Number(await p.locator('[data-resource-value="Coin"]').innerText());assert.ok(shown>=8&&shown<108);assert.equal(await p.locator('[data-resource-box="Coin"]').evaluate(e=>getComputedStyle(e).animationDuration),'0.8s');await p.waitForTimeout(950);assert.equal(await p.locator('[data-resource-value="Coin"]').innerText(),'108');assert.equal(await p.locator('[data-resource-value="Fate"]').innerText(),'24');assert.equal(await p.locator('.resource-reward').count(),0);assert.deepEqual(await read(p),saved);});
test('125 hidden Resources stays collapsed on victory and reopening shows final totals without replay',async p=>{await load(p);await random(p);await defineEnemy(p,{base:4,fate:2,coin:3});await pick(p,['C5']);await click(p,'#combatCommit');await click(p,'#resourcesToggle');await click(p,'#combatResolve');assert.equal(await p.locator('#resourcesBody').isVisible(),false);assert.equal(await p.locator('.resource-reward').count(),0);assert.equal((await read(p)).res.Coin,11);await click(p,'#resourcesToggle');assert.equal(await p.locator('[data-resource-value="Coin"]').innerText(),'11');assert.equal(await p.locator('.resource-reward').count(),0);});
test('126 animation callbacks never change another character and a pending item reward never replays resource animation',async p=>{await seed(p,[slot(fixture(),'one'),slot(fixture(),'two')]);await click(p,'[data-continue="one"]');await random(p);await defineEnemy(p,{base:4,fate:20,coin:100});await pick(p,['C5']);await click(p,'#combatCommit');await click(p,'#combatResolve');await click(p,'#newGameTop');await click(p,'[data-continue="two"]');await p.waitForTimeout(950);assert.equal((await read(p,'one')).res.Coin,108);assert.equal((await read(p,'two')).res.Coin,8);assert.equal(await p.locator('[data-resource-value="Coin"]').innerText(),'8');assert.equal(await p.locator('.resource-reward').count(),0);await load(p,fixture({inventory:inventoryEight()}));await random(p);await defineEnemy(p,{base:4,fate:2,coin:3,item:rewardItem});await pick(p,['C5']);await click(p,'#combatCommit');await click(p,'#combatResolve');await p.reload();await click(p,'[data-continue="one"]');assert.equal(await p.locator('.resource-reward').count(),0);assert.equal(await p.locator('[data-resource-value="Coin"]').innerText(),'11');assert.equal(await p.locator('#combatRewardModal').isVisible(),true);});
test('127 reduced motion disables shaking/count-up but retains a quiet temporary wound tint',async p=>{await p.emulateMedia({reducedMotion:'reduce'});await load(p);await random(p);await defineEnemy(p,{base:4,fate:2,coin:3});await pick(p,['C5']);await click(p,'#combatCommit');await click(p,'#combatResolve');assert.equal(await p.locator('.resource-reward').count(),0);assert.equal(await p.locator('[data-resource-value="Coin"]').innerText(),'11');await action(p,'wound');await p.locator('#woundValue').fill('1');await click(p,'#beginWound');await pick(p,['C5']);await click(p,'#woundNext');assert.equal(await p.locator('main').evaluate(e=>e.classList.contains('wound-shake')),false);assert.equal(await p.locator('#woundOverlay').evaluate(e=>getComputedStyle(e).animationName),'none');assert.equal(await p.locator('#woundOverlay').evaluate(e=>getComputedStyle(e).opacity),'0.12');await p.waitForTimeout(600);assert.equal(await p.locator('#woundOverlay').evaluate(e=>e.classList.contains('active')),false);});
test('128 Undo cancels transient effects and restores actual resource and wound values',async p=>{await load(p);await random(p);await defineEnemy(p,{base:4,fate:2,coin:3});await pick(p,['C5']);await click(p,'#combatCommit');await click(p,'#combatResolve');await click(p,'#undo');assert.equal((await read(p)).res.Coin,8);assert.equal(await p.locator('.resource-reward').count(),0);await p.waitForTimeout(900);assert.equal(await p.locator('[data-resource-value="Coin"]').innerText(),'8');await click(p,'#cancelEncounter');await load(p,fixture({zones:{deck:['H3'],hand:[],fatigue:['C5','H2'],wound:[]}}));await action(p,'wound');await p.locator('#woundValue').fill('5');await click(p,'#beginWound');await pick(p,['C5']);await click(p,'#woundNext');await p.locator('#undo').evaluate(e=>e.click());assert.equal(await p.locator('#woundOverlay').evaluate(e=>e.classList.contains('active')),false);assert.deepEqual((await read(p)).zones.wound,[]);});
test('129 new resource layout, large totals and adjustment dialogs fit desktop and narrow screens',async(p,ctx,browser)=>{const c=await browser.newContext({viewport:{width:320,height:844},isMobile:true,hasTouch:true});try{const q=await c.newPage();await q.goto(p.url());await load(q);assert.equal(await q.locator('#resources input').count(),0);for(const key of ['Coin','Fate','Supply']){const boxes=await q.locator(`[data-resource-box="${key}"] .resource-controls>button`).evaluateAll(es=>es.map(e=>({x:e.getBoundingClientRect().x,width:e.getBoundingClientRect().width})));assert.ok(boxes[0].x<boxes[1].x&&boxes[1].x<boxes[2].x);assert.ok(boxes[0].width>=44&&boxes[2].width>=44)}await q.locator('[data-adjust-resource="Coin"]').tap();await q.locator('#adjustAmount').fill('5');assert.equal(await q.locator('#adjustPreview').innerText(),'New total: 13');await q.screenshot({path:path.join(OUT,'v20-resource-dialog-mobile.png')});await click(q,'#adjustCancel');await load(q,fixture({round:Number.MAX_SAFE_INTEGER,res:{Coin:Number.MAX_SAFE_INTEGER,Fate:Number.MAX_SAFE_INTEGER,Supply:Number.MAX_SAFE_INTEGER}}));for(const width of [320,390,600,601,800,801,900]){await q.setViewportSize({width,height:900});assert.ok(await q.evaluate(()=>document.documentElement.scrollWidth<=innerWidth));assert.ok(await q.locator('.resource-total').evaluateAll(es=>es.every(e=>e.scrollWidth<=e.clientWidth)))}await q.locator('#roundDisplay').tap();await q.keyboard.press('Escape');}finally{await c.close()}});
test('130 adjustment dialog keyboard focus is contained and returned to the edited total',async p=>{await load(p);await click(p,'[data-adjust-resource="Fate"]');await p.locator('#adjustAdd').focus();await p.keyboard.press('Shift+Tab');assert.equal(await p.locator(':focus').getAttribute('id'),'adjustConfirm');await p.keyboard.press('Tab');assert.equal(await p.locator(':focus').getAttribute('id'),'adjustAdd');await p.keyboard.press('Escape');assert.equal(await p.locator(':focus').getAttribute('data-adjust-resource'),'Fate');await manualAmount(p,'Fate',3);assert.equal(await p.locator(':focus').getAttribute('data-adjust-resource'),'Fate');assert.equal((await read(p)).res.Fate,7);});
test('131 V20 resource, Round, floored combat and Rest work offline without external requests',async(p,ctx,browser)=>{const c=await browser.newContext({offline:true});try{const q=await c.newPage(),origin=new URL(p.url()).origin,external=[];q.setDefaultTimeout(2500);await c.route('**/*',r=>{if(new URL(r.request().url()).origin===origin)return r.fulfill({status:200,contentType:'text/html',body:fs.readFileSync(APP_FILE)});external.push(r.request().url());return r.abort()});await q.goto(origin);await load(q);await manualAmount(q,'Coin',5);await manualAmount(q,'Round',2);await random(q,0);await defineEnemy(q,{base:1,fate:2,coin:3});await pick(q,['H1']);await click(q,'#combatCommit');await click(q,'#combatResolve');await click(q,'#combatExact');await action(q,'rest');await q.locator('#target').fill('1');await pick(q,['H1']);await click(q,'#commit');const s=await read(q);assert.equal(s.round,3);assert.deepEqual(s.res,{Coin:16,Fate:6,Supply:1});assert.deepEqual(external,[]);invariant(s);}finally{await c.close()}});

(async()=>{fs.mkdirSync(OUT,{recursive:true});const source=fs.readFileSync(APP_FILE);const server=http.createServer((req,res)=>{if(req.url==='/favicon.ico'){res.writeHead(204).end();return;}res.setHeader('Content-Type','text/html; charset=utf-8');res.end(source);});await new Promise(r=>server.listen(0,'127.0.0.1',r));const origin=`http://127.0.0.1:${server.address().port}`;let browser;const results=[];try{browser=await chromium.launch({executablePath:process.env.CHROMIUM_PATH||(fs.existsSync('/usr/bin/chromium')?'/usr/bin/chromium':undefined),headless:true,args:['--no-sandbox']});for(const c of cases.filter(c=>!process.env.TEST_FILTER||new RegExp(process.env.TEST_FILTER).test(c.name))){const context=await browser.newContext({acceptDownloads:true});await context.route('**/*',route=>new URL(route.request().url()).origin===origin?route.continue():route.abort());const page=await context.newPage();page.setDefaultTimeout(2500);const errors=[];page.on('pageerror',e=>errors.push(e.message));const started=Date.now();try{await page.goto(origin);await c.fn(page,context,browser);assert.deepEqual(errors,[],'no unhandled browser errors');results.push({name:c.name,status:'PASS',ms:Date.now()-started});}catch(e){results.push({name:c.name,status:'FAIL',error:e.message,errors,ms:Date.now()-started});await page.screenshot({path:path.join(OUT,`failure-${c.name.slice(0,2)}.png`),fullPage:true}).catch(()=>{});}console.log(results.at(-1).status,c.name,results.at(-1).error||'');await context.close();}const summary={date:new Date().toISOString(),browser:browser.version(),sourceSHA256:require('node:crypto').createHash('sha256').update(source).digest('hex'),passed:results.filter(r=>r.status==='PASS').length,failed:results.filter(r=>r.status==='FAIL').length,results};fs.writeFileSync(path.join(OUT,process.env.TEST_FILTER?'filtered-results.json':'baseline-results.json'),JSON.stringify(summary,null,2));console.log(JSON.stringify({passed:summary.passed,failed:summary.failed}));process.exitCode=summary.failed?1:0;}finally{if(browser)await browser.close();server.close();}})();
